export interface InstructionPreference { current: number; completed: string[] }
export type InstructionPreferences = Partial<Record<MissionId, InstructionPreference>>;
/** Ignore invalid/stale local preferences rather than affecting the saved attempt. */
export function parseInstructionPreferences(raw: string | null): InstructionPreferences {
  if (!raw) return {};
  try {
    const parsed: unknown = JSON.parse(raw);
    if (!parsed || typeof parsed !== "object") return {};
    const result: InstructionPreferences = {};
    for (const mission of missions) {
      const entry: unknown = (parsed as Record<string, unknown>)[mission.key];
      if (!entry || typeof entry !== "object") continue;
      const value = entry as Record<string, unknown>;
      const steps = instructionSteps[mission.key];
      const current = typeof value['current'] === "number" && Number.isInteger(value['current']) && value['current'] >= 0 && value['current'] < steps.length ? value['current'] : 0;
      const validIds = new Set(steps.map((step) => step.id));
      const completed = Array.isArray(value['completed']) ? [...new Set(value['completed'].filter((id): id is string => typeof id === "string" && validIds.has(id)))] : [];
      result[mission.key] = { current, completed };
    }
    return result;
  } catch { return {}; }
}
export function instructionProgress(steps: InstructionStep[], preference?: InstructionPreference) {
  const completed = new Set(preference?.completed ?? []);
  return {
    current: Math.max(0, Math.min(preference?.current ?? 0, steps.length - 1)),
    completed: steps.filter((step) => completed.has(step.id)).length,
    remaining: steps.filter((step) => !completed.has(step.id)).length,
  };
}
